use dioxus::prelude::*;
use gloo_net::http::Request;
use serde::{Deserialize, Serialize};
use wasm_bindgen_futures::spawn_local;

const API_BASE: &str = "http://localhost:8000/api/v1";
const APP_CSS: &str = r#"
body { font-family: 'Segoe UI', sans-serif; margin: 0; background: #f7f8fa; }
.layout { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; }
.sidebar { background: #0f2d40; color: white; padding: 20px; }
.menu-item { padding: 8px 10px; margin: 4px 0; border-radius: 6px; background: #1e445d; }
.content { padding: 24px; }
.card { background: white; border-radius: 8px; padding: 16px; margin-bottom: 14px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); }
input, select, button { padding: 8px; margin: 4px 0; width: 100%; box-sizing: border-box; }
"#;

fn main() {
    dioxus::launch(App);
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Role {
    Admin,
    Coordinator,
    Proctor,
    Auditor,
}

impl Role {
    fn label(self) -> &'static str {
        match self {
            Role::Admin => "Admin",
            Role::Coordinator => "Coordinator",
            Role::Proctor => "Proctor",
            Role::Auditor => "Auditor",
        }
    }

    fn can_view_admin(self) -> bool {
        matches!(self, Role::Admin)
    }

    fn can_view_inventory(self) -> bool {
        matches!(self, Role::Admin | Role::Coordinator)
    }
}

#[derive(Debug, Deserialize, Clone, Default)]
struct LoginResponse {
    session_id: String,
    jwt: String,
    session_expires_at: String,
    jwt_expires_at: String,
}

#[derive(Debug, Deserialize, Clone)]
struct CandidateRow {
    id: String,
    scanned_barcode: String,
}

#[derive(Debug, Deserialize, Clone, Default)]
struct DashboardSummary {
    seat_utilization_count: usize,
    near_expiry_count: usize,
    incident_rate_count: usize,
}

#[derive(Serialize)]
struct LoginRequest {
    username: String,
    password: String,
}

#[derive(Serialize)]
struct CreateSessionRequest {
    id: String,
    template_name: String,
    duration_minutes: i32,
    status: String,
    starts_at: String,
    ends_at: String,
}

#[derive(Serialize)]
struct GenerateOutputRequest {
    session_id: String,
    mode: String,
    output_type: String,
}

#[component]
fn App() -> Element {
    let mut role = use_signal(|| Role::Proctor);
    let mut username = use_signal(|| "".to_string());
    let mut password = use_signal(|| "".to_string());
    let mut token = use_signal(|| None::<LoginResponse>);
    let mut login_status = use_signal(|| "Not authenticated".to_string());
    let mut candidates = use_signal(Vec::<CandidateRow>::new);
    let mut dashboard = use_signal(DashboardSummary::default);
    let mut action_status = use_signal(|| "Idle".to_string());

    let role_now = role();

    rsx! {
        document::Style { "{APP_CSS}" }

        div { class: "layout",
            aside { class: "sidebar",
                h2 { "Eagle Ops" }
                p { "Role: {role_now.label()}" }
                select {
                    onchange: move |evt| {
                        let next = match evt.value().as_str() {
                            "Admin" => Role::Admin,
                            "Coordinator" => Role::Coordinator,
                            "Proctor" => Role::Proctor,
                            _ => Role::Auditor,
                        };
                        role.set(next);
                    },
                    option { value: "Admin", "Admin" }
                    option { value: "Coordinator", "Coordinator" }
                    option { value: "Proctor", selected: true, "Proctor" }
                    option { value: "Auditor", "Auditor" }
                }
                div { class: "menu-item", "Dashboard" }
                div { class: "menu-item", "Operations & Reporting Center" }
                if role_now.can_view_inventory() {
                    div { class: "menu-item", "Inventory" }
                }
                if role_now.can_view_admin() {
                    div { class: "menu-item", "Admin Panel" }
                }
            }

            main { class: "content",
                div { class: "card",
                    h3 { "Login" }
                    input {
                        placeholder: "Enter username",
                        value: "{username}",
                        oninput: move |e| username.set(e.value().clone())
                    }
                    input {
                        r#type: "password",
                        placeholder: "Enter password",
                        value: "{password}",
                        oninput: move |e| password.set(e.value().clone())
                    }
                    button {
                        onclick: move |_| {
                            let username_v = username();
                            let password_v = password();
                            let mut token_sig = token;
                            let mut login_status_sig = login_status;
                            spawn_local(async move {
                                let body = LoginRequest { username: username_v, password: password_v };
                                let res = Request::post(&format!("{API_BASE}/auth/login"))
                                    .header("Content-Type", "application/json")
                                    .body(serde_json::to_string(&body).unwrap())
                                    .unwrap()
                                    .send()
                                    .await;

                                match res {
                                    Ok(resp) if resp.ok() => {
                                        let parsed: LoginResponse = resp.json().await.unwrap_or_default();
                                        token_sig.set(Some(parsed));
                                        login_status_sig.set("Authenticated".to_string());
                                    }
                                    Ok(resp) => login_status_sig.set(format!("Login failed: {}", resp.status())),
                                    Err(_) => login_status_sig.set("Login request error".to_string()),
                                }
                            });
                        },
                        "Login"
                    }
                    p { "{login_status}" }
                }

                div { class: "card",
                    h3 { "Dashboard" }
                    button {
                        onclick: move |_| {
                            let tok = token();
                            let mut dash_sig = dashboard;
                            let mut status_sig = action_status;
                            spawn_local(async move {
                                let Some(tok) = tok else {
                                    status_sig.set("Login first".to_string());
                                    return;
                                };
                                let res = Request::get(&format!("{API_BASE}/reports/dashboard"))
                                    .header("Authorization", &format!("Bearer {}", tok.jwt))
                                    .header("x-session-id", &tok.session_id)
                                    .send()
                                    .await;
                                match res {
                                    Ok(resp) if resp.ok() => {
                                        let parsed: DashboardSummary = resp.json().await.unwrap_or_default();
                                        dash_sig.set(parsed);
                                        status_sig.set("Dashboard loaded".to_string());
                                    }
                                    Ok(resp) => status_sig.set(format!("Dashboard failed: {}", resp.status())),
                                    Err(_) => status_sig.set("Dashboard request error".to_string()),
                                }
                            });
                        },
                        "Load Dashboard"
                    }
                    p { "Seat Utilization Rows: {dashboard().seat_utilization_count}" }
                    p { "Near Expiry Rows: {dashboard().near_expiry_count}" }
                    p { "Incident Rate Rows: {dashboard().incident_rate_count}" }
                }

                div { class: "card",
                    h3 { "Candidates" }
                    button {
                        onclick: move |_| {
                            let tok = token();
                            let mut list_sig = candidates;
                            let mut status_sig = action_status;
                            spawn_local(async move {
                                let Some(tok) = tok else {
                                    status_sig.set("Login first".to_string());
                                    return;
                                };
                                let res = Request::get(&format!("{API_BASE}/candidates?page=1&limit=20"))
                                    .header("Authorization", &format!("Bearer {}", tok.jwt))
                                    .header("x-session-id", &tok.session_id)
                                    .send()
                                    .await;
                                match res {
                                    Ok(resp) if resp.ok() => {
                                        let parsed: Vec<CandidateRow> = resp.json().await.unwrap_or_default();
                                        list_sig.set(parsed);
                                        status_sig.set("Candidates loaded".to_string());
                                    }
                                    Ok(resp) => status_sig.set(format!("Candidates failed: {}", resp.status())),
                                    Err(_) => status_sig.set("Candidates request error".to_string()),
                                }
                            });
                        },
                        "Load Candidates"
                    }
                    ul {
                        for c in candidates() {
                            li { "{c.id} | {c.scanned_barcode}" }
                        }
                    }
                }

                div { class: "card",
                    h3 { "Session + Output Actions" }
                    button {
                        onclick: move |_| {
                            let tok = token();
                            let mut status_sig = action_status;
                            spawn_local(async move {
                                let Some(tok) = tok else {
                                    status_sig.set("Login first".to_string());
                                    return;
                                };
                                let session = CreateSessionRequest {
                                    id: format!("sess-{}", js_sys::Date::now() as i64),
                                    template_name: "default-template".to_string(),
                                    duration_minutes: 60,
                                    status: "Scheduled".to_string(),
                                    starts_at: "03/27/2026 09:00 AM".to_string(),
                                    ends_at: "03/27/2026 10:00 AM".to_string(),
                                };
                                let res = Request::post(&format!("{API_BASE}/sessions"))
                                    .header("Authorization", &format!("Bearer {}", tok.jwt))
                                    .header("x-session-id", &tok.session_id)
                                    .header("Content-Type", "application/json")
                                    .body(serde_json::to_string(&session).unwrap())
                                    .unwrap()
                                    .send()
                                    .await;
                                match res {
                                    Ok(resp) if resp.ok() => status_sig.set("Session created".to_string()),
                                    Ok(resp) => status_sig.set(format!("Session create failed: {}", resp.status())),
                                    Err(_) => status_sig.set("Session request error".to_string()),
                                }
                            });
                        },
                        "Create Session"
                    }

                    button {
                        onclick: move |_| {
                            let tok = token();
                            let mut status_sig = action_status;
                            spawn_local(async move {
                                let Some(tok) = tok else {
                                    status_sig.set("Login first".to_string());
                                    return;
                                };
                                let payload = GenerateOutputRequest {
                                    session_id: "sess-demo".to_string(),
                                    mode: "TestPrint".to_string(),
                                    output_type: "AdmitCard".to_string(),
                                };
                                let res = Request::post(&format!("{API_BASE}/outputs"))
                                    .header("Authorization", &format!("Bearer {}", tok.jwt))
                                    .header("x-session-id", &tok.session_id)
                                    .header("Content-Type", "application/json")
                                    .body(serde_json::to_string(&payload).unwrap())
                                    .unwrap()
                                    .send()
                                    .await;
                                match res {
                                    Ok(resp) if resp.ok() => status_sig.set("Output generated".to_string()),
                                    Ok(resp) => status_sig.set(format!("Output failed: {}", resp.status())),
                                    Err(_) => status_sig.set("Output request error".to_string()),
                                }
                            });
                        },
                        "Generate Output"
                    }

                    if let Some(tok) = token() {
                        p { "JWT expires: {tok.jwt_expires_at}" }
                        p { "Session expires: {tok.session_expires_at}" }
                    }
                    p { "Action status: {action_status}" }
                }

                div { class: "card",
                    h3 { "Template Configuration" }
                    p { "TODO: Implement admin template configuration form builder UI (fields, validations, versioning controls)." }
                }

                div { class: "card",
                    h3 { "QR / Barcode Capture" }
                    input { placeholder: "Scan or enter QR/Barcode value" }
                    p { "TODO: Wire scanner device events and submit to candidate/session lookup endpoint." }
                }

                div { class: "card",
                    h3 { "Attachment Capture" }
                    p { "TODO: Implement drag-and-drop upload component with preview, file policy validation, and metadata capture." }
                }
            }
        }
    }
}

