                    p { class: "mt-4 text-slate-300", "Securely manage candidates, assets, exam rooms, reports, and output workflows from one dashboard." }
                    ul { class: "mt-6 space-y-2 text-sm text-slate-300",
                        li { "Role-aware operations" }
                        li { "Traceable audit workflows" }
                        li { "Fast session and output dispatch" }
                    }
                }

                div { class: "p-8 md:p-10",
                    h2 { class: "text-2xl font-bold text-slate-900", "Sign in" }
                    p { class: "mt-2 text-sm text-slate-500", "Use seeded credentials to access protected pages." }

                    div { class: "mt-6 space-y-4",
                        div {
                            label { class: "block text-sm font-medium text-slate-700 mb-1", "Username" }
                            input {
                                class: "w-full rounded-lg border border-slate-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition",
                                value: "{username}",
                                oninput: move |evt| username.set(evt.value()),
                            }
                        }
                        div {
                            label { class: "block text-sm font-medium text-slate-700 mb-1", "Password" }
                            input {
                                r#type: "password",
                                class: "w-full rounded-lg border border-slate-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition",
                                value: "{password}",
                                oninput: move |evt| password.set(evt.value()),
                            }
                        }
                        button {
                            class: "w-full rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2.5 transition",
                            onclick: move |_| {
                                let user = username();
                                let pass = password();
                                let mut session_sig = auth.session;
                                let mut global_status = auth.global_status;
                                let mut status_sig = status;
                                let nav = nav.clone();

                                spawn_local(async move {
                                    status_sig.set("Authenticating...".to_string());
                                    let body = LoginRequest { username: user, password: pass };
                                    let request = Request::post(&format!("{API_BASE}/auth/login"))
                                        .header("Content-Type", "application/json")
                                        .body(serde_json::to_string(&body).unwrap());

                                    let Ok(request) = request else {
                                        status_sig.set("Failed to build login request".to_string());
                                        return;
                                    };

                                    match request.send().await {
                                        Ok(resp) if resp.ok() => {
                                            let parsed: LoginResponse = resp.json().await.unwrap_or_default();
                                            session_sig.set(Some(parsed.clone()));
                                            save_session_to_storage(&parsed);
                                            status_sig.set("Login successful".to_string());
                                            global_status.set("Authenticated".to_string());
                                            nav.replace(Route::Dashboard {});
                                        }
                                        Ok(resp) => {
                                            status_sig.set(format!("Login failed: HTTP {}", resp.status()));
                                        }
                                        Err(err) => {
                                            status_sig.set(format!("Login request failed: {err}"));
                                        }
                                    }
                                });
                            },
                            "Sign In"
                        }
                    }

                    p { class: "mt-4 text-sm text-slate-500", "{status}" }
                }
            }
        }
    }
}

