            p { class: "mt-3 text-sm text-slate-600", "{status}" }
            data_table_assets(rows())

            div { class: "mt-8 rounded-xl border border-slate-200 bg-white p-4",
                h3 { class: "text-lg font-semibold text-slate-900", "Attachment Capture" }
                p { class: "text-sm text-slate-600 mt-1", "Drag and drop files here or click to browse. Allowed: jpg/png/mp4/mp3/pdf/docx, max 25MB each, up to 10 files." }

                div { class: "mt-4",
                    label { class: "block text-sm text-slate-700 mb-1", "Record ID" }
                    input {
                        class: "w-full sm:w-96 rounded-lg border border-slate-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500",
                        value: "{record_id}",
                        oninput: move |evt| record_id.set(evt.value()),
                    }
                }

                div { class: "mt-4 relative rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 p-8 text-center hover:border-blue-400 transition",
                    p { class: "text-sm text-slate-700", "Drop files here or click to upload" }
                    input {
                        class: "absolute inset-0 opacity-0 cursor-pointer",
                        r#type: "file",
                        multiple: true,
                        accept: ".jpg,.jpeg,.png,.mp4,.mp3,.pdf,.docx",
                        onchange: move |evt| {
                            let Some(file_engine) = evt.files() else {
                                return;
                            };
                            let mut files_sig = files;
                            let mut attach_status_sig = attach_status;
                            spawn_local(async move {
                                let mut pending = files_sig();
                                let names = file_engine.files();

                                for file_name in names {
                                    if pending.len() >= 10 {
                                        attach_status_sig.set("Maximum 10 files per record exceeded".to_string());
                                        break;
                                    }

                                    let ext = file_extension(&file_name);
                                    if !is_allowed_ext(&ext) {
                                        attach_status_sig.set(format!("Skipped {file_name}: file type not allowed"));
                                        continue;
                                    }

                                    let Some(bytes) = file_engine.read_file(&file_name).await else {
                                        attach_status_sig.set(format!("Failed reading {file_name}"));
                                        continue;
                                    };

                                    if bytes.len() > 25 * 1024 * 1024 {
                                        attach_status_sig.set(format!("Skipped {file_name}: exceeds 25MB"));
                                        continue;
                                    }

                                    let mime = mime_for_ext(&ext);
                                    let preview = if is_image_ext(&ext) {
                                        let b64 = base64::engine::general_purpose::STANDARD.encode(&bytes);
                                        Some(format!("data:{mime};base64,{b64}"))
                                    } else {
                                        None
                                    };

                                    pending.push(PendingFile {
                                        name: file_name,
                                        extension: ext,
                                        mime_type: mime.to_string(),
                                        size_bytes: bytes.len(),
                                        bytes,
                                        preview_data_url: preview,
                                    });
                                }

                                let count = pending.len();
                                files_sig.set(pending);
                                attach_status_sig.set(format!("{count} file(s) staged"));
                            });
                        },
                    }
                }

                if files().is_empty() {
                    p { class: "mt-4 text-sm text-slate-500", "No files selected yet." }
                } else {
                    div { class: "mt-4 grid gap-3",
                        for file in files() {
                            div { class: "rounded-lg border border-slate-200 p-3 bg-white flex items-start justify-between gap-3",
                                div {
                                    p { class: "font-medium text-slate-800", "{file.name}" }
                                    p { class: "text-xs text-slate-500", "{file.mime_type} | {human_size(file.size_bytes)}" }
                                }
                                if let Some(url) = file.preview_data_url {
                                    img { class: "w-16 h-16 object-cover rounded-md border border-slate-200", src: "{url}" }
                                } else {
                                    span { class: "text-xs px-2 py-1 rounded bg-slate-100 text-slate-600", "No preview" }
                                }
                            }
                        }
                    }
                }

                button {
                    class: "mt-4 rounded-lg bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-400 text-white px-4 py-2 font-semibold transition",
                    disabled: files().is_empty(),
                    onclick: move |_| {
                        let files_to_upload = files();
                        let session = auth.session();
                        let record_id = record_id();
                        let mut attach_status_sig = attach_status;
                        spawn_local(async move {
                            let Some(session) = session else {
                                attach_status_sig.set("Session missing".to_string());
                                return;
                            };

                            let mut ok_count = 0usize;
                            for file in &files_to_upload {
                                let payload = AttachmentUploadRequest {
                                    record_type: "assets".to_string(),
                                    record_id: record_id.clone(),
                                    file_name: file.name.clone(),
                                    extension: file.extension.clone(),
                                    bytes_base64: base64::engine::general_purpose::STANDARD.encode(&file.bytes),
                                    operator_label: "web-admin".to_string(),
                                    device_label: "browser".to_string(),
                                };

                                match authed_post_empty("/attachments", &payload, &session).await {
                                    Ok(()) => ok_count += 1,
                                    Err(err) => {
                                        attach_status_sig.set(format!("Upload failed for {}: {}", file.name, err));
                                        return;
                                    }
                                }
                            }

                            attach_status_sig.set(format!("Uploaded {ok_count} file(s) successfully"));
                        });
                    },
                    "Upload Files"
                }
                p { class: "mt-3 text-sm text-slate-600", "{attach_status}" }
            }
        }
    }
}

