#[component]
fn Templates() -> Element {
    if !ensure_authenticated() {
        return rsx! { div { class: "p-6", "Redirecting to login..." } };
    }

    let auth = use_context::<AuthContext>();
    let mut template_id = use_signal(|| "candidate-registration".to_string());
    let mut lock_for_final = use_signal(|| false);
    let mut version_no = use_signal(|| 1i32);
    let mut fields = use_signal(|| {
        vec![TemplateFieldState {
            name: "candidate_name".to_string(),
            label: "Candidate Name".to_string(),
            field_type: FieldType::Text,
            required: true,
            min_len: Some(2),
            max_len: Some(120),
        }]
    });
    let mut status = use_signal(|| "Configure and save template".to_string());
    let mut versions = use_signal(Vec::<TemplateVersionRow>::new);

    rsx! {
        Shell { title: "Template Configuration", active: Route::Templates {},
            panel_title("Template Configuration", "Define fields and validation rules for candidate registration")

            div { class: "grid grid-cols-1 lg:grid-cols-2 gap-6",
                div { class: "rounded-xl border border-slate-200 bg-white p-4",
                    label { class: "block text-sm font-medium text-slate-700 mb-1", "Template ID" }
                    input {
                        class: "w-full rounded-lg border border-slate-300 px-3 py-2",
                        value: "{template_id}",
                        oninput: move |evt| template_id.set(evt.value()),
                    }

                    div { class: "mt-3 flex items-center gap-3",
                        label { class: "text-sm text-slate-700", "Version" }
                        input {
                            r#type: "number",
                            class: "w-28 rounded-lg border border-slate-300 px-3 py-2",
                            value: "{version_no}",
                            oninput: move |evt| {
                                let parsed = evt.value().parse::<i32>().unwrap_or(1);
                                version_no.set(parsed.max(1));
                            },
                        }
                        label { class: "inline-flex items-center gap-2 text-sm text-slate-700",
                            input {
                                r#type: "checkbox",
                                checked: lock_for_final(),
                                onchange: move |_| lock_for_final.set(!lock_for_final()),
                            }
                            "Lock for final print"
                        }
                    }

                    h4 { class: "mt-5 font-semibold text-slate-900", "Fields" }
                    div { class: "mt-3 space-y-3",
                        for (idx, item) in fields().into_iter().enumerate() {
                            div { class: "rounded-lg border border-slate-200 p-3 bg-slate-50",
                                div { class: "grid grid-cols-1 md:grid-cols-2 gap-2",
                                    input {
                                        class: "rounded-lg border border-slate-300 px-3 py-2",
                                        placeholder: "Field name",
                                        value: "{item.name}",
                                        oninput: move |evt| {
                                            let mut state = fields();
                                            if let Some(entry) = state.get_mut(idx) {
                                                entry.name = evt.value();
                                            }
                                            fields.set(state);
                                        },
                                    }
                                    input {
                                        class: "rounded-lg border border-slate-300 px-3 py-2",
                                        placeholder: "Field label",
                                        value: "{item.label}",
                                        oninput: move |evt| {
                                            let mut state = fields();
                                            if let Some(entry) = state.get_mut(idx) {
                                                entry.label = evt.value();
                                            }
                                            fields.set(state);
                                        },
                                    }
                                    select {
                                        class: "rounded-lg border border-slate-300 px-3 py-2",
                                        value: "{item.field_type.as_str()}",
                                        onchange: move |evt| {
                                            let mut state = fields();
                                            if let Some(entry) = state.get_mut(idx) {
                                                entry.field_type = match evt.value().as_str() {
                                                    "number" => FieldType::Number,
                                                    "date" => FieldType::Date,
                                                    "select" => FieldType::Select,
                                                    _ => FieldType::Text,
                                                };
                                            }
                                            fields.set(state);
                                        },
                                        option { value: "text", "Text" }
                                        option { value: "number", "Number" }
                                        option { value: "date", "Date" }
                                        option { value: "select", "Select" }
                                    }
                                    label { class: "inline-flex items-center gap-2 text-sm text-slate-700",
                                        input {
                                            r#type: "checkbox",
                                            checked: item.required,
                                            onchange: move |_| {
                                                let mut state = fields();
                                                if let Some(entry) = state.get_mut(idx) {
                                                    entry.required = !entry.required;
                                                }
                                                fields.set(state);
                                            },
                                        }
                                        "Required"
                                    }
                                }
                            }
                        }
                    }

                    div { class: "mt-3 flex flex-wrap gap-3",
                        button {
                            class: "rounded-lg bg-slate-700 hover:bg-slate-800 text-white px-3 py-2 text-sm font-semibold transition",
                            onclick: move |_| {
                                let mut state = fields();
                                state.push(TemplateFieldState {
                                    name: "new_field".to_string(),
                                    label: "New Field".to_string(),
                                    field_type: FieldType::Text,
                                    required: false,
                                    min_len: None,
                                    max_len: None,
                                });
                                fields.set(state);
                            },
                            "Add Field"
                        }

                        button {
                            class: "rounded-lg bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 text-sm font-semibold transition",
                            onclick: move |_| {
                                let tid = template_id();
                                let version = version_no();
                                let lock = lock_for_final();
                                let field_data = fields();
                                let session = auth.session();
                                let mut status_sig = status;

                                spawn_local(async move {
                                    if tid.trim().is_empty() {
                                        status_sig.set("Template ID is required".to_string());
                                        return;
                                    }

                                    let Some(session) = session else {
                                        status_sig.set("Session missing".to_string());
                                        return;
                                    };

                                    let snapshot = serde_json::json!({
                                        "fields": field_data.iter().map(|f| {
                                            serde_json::json!({
                                                "name": f.name,
                                                "label": f.label,
                                                "field_type": f.field_type.as_str(),
                                                "required": f.required,
                                                "validation": {
                                                    "min_len": f.min_len,
                                                    "max_len": f.max_len
                                                }
                                            })
                                        }).collect::<Vec<_>>()
                                    });

                                    let payload = CreateTemplateRequest {
                                        template_id: tid.clone(),
                                        version_no: version,
                                        snapshot,
                                        lock_for_final_print: lock,
                                    };

                                    match authed_post_empty("/templates", &payload, &session).await {
                                        Ok(()) => status_sig.set(format!("Template {tid} v{version} saved")),
                                        Err(err) => {
                                            web_sys::console::log_1(&format!("Template save fallback: {err}").into());
                                            status_sig.set(format!("Template {tid} stored locally (backend stub fallback)"));
                                        }
                                    }
                                });
                            },
                            "Save Template"
                        }

                        button {
                            class: "rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 text-sm font-semibold transition",
                            onclick: move |_| {
                                let session = auth.session();
                                let mut versions_sig = versions;
                                let mut status_sig = status;
                                spawn_local(async move {
                                    let Some(session) = session else {
                                        status_sig.set("Session missing".to_string());
                                        return;
                                    };
                                    match authed_get_json::<Vec<TemplateVersionRow>>("/templates", &session).await {
                                        Ok(data) => {
                                            versions_sig.set(data);
                                            status_sig.set("Template versions loaded".to_string());
                                        }
                                        Err(err) => status_sig.set(err),
                                    }
                                });
                            },
                            "Load Versions"
                        }
                    }
                    p { class: "mt-3 text-sm text-slate-600", "{status}" }
                }

                div { class: "rounded-xl border border-slate-200 bg-white p-4",
                    h4 { class: "font-semibold text-slate-900", "Saved Template Versions" }
                    if versions().is_empty() {
                        p { class: "mt-3 text-sm text-slate-500", "No template versions loaded yet." }
                    } else {
                        div { class: "mt-3 space-y-2",
                            for row in versions() {
                                div { class: "rounded-lg border border-slate-200 p-3",
                                    p { class: "font-medium text-slate-800", "{row.template_id} v{row.version_no}" }
                                    p { class: "text-xs text-slate-500", "Created by {row.created_by} at {row.created_at}" }
                                    if row.locked_for_final_print {
                                        span { class: "inline-block mt-2 text-xs px-2 py-1 rounded bg-amber-100 text-amber-700", "Locked" }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

