fn load_session_from_storage() -> Option<LoginResponse> {
    let Some(storage) = browser_storage() else {
        return None;
    };

    let raw = storage.get_item(SESSION_STORAGE_KEY).ok().flatten()?;
    serde_json::from_str::<LoginResponse>(&raw).ok()
}

fn save_session_to_storage(session: &LoginResponse) {
    if let Some(storage) = browser_storage() {
        let _ = storage.set_item(
            SESSION_STORAGE_KEY,
            &serde_json::to_string(session).unwrap_or_default(),
        );
    }
}

fn clear_session_from_storage() {
    if let Some(storage) = browser_storage() {
        let _ = storage.remove_item(SESSION_STORAGE_KEY);
    }
}

fn browser_storage() -> Option<web_sys::Storage> {
    web_sys::window()?.local_storage().ok().flatten()
}

async fn authed_get_json<T: for<'de> Deserialize<'de>>(path: &str, session: &LoginResponse) -> Result<T, String> {
    let request = Request::get(&format!("{API_BASE}{path}"))
        .header("Authorization", &format!("Bearer {}", session.jwt))
        .header("x-session-id", &session.session_id);

    let response = request.send().await.map_err(|e| format!("Request failed: {e}"))?;
    if !response.ok() {
        return Err(format!("HTTP {}", response.status()));
    }

    response
        .json::<T>()
        .await
        .map_err(|e| format!("Failed to decode response: {e}"))
}

async fn authed_post_empty<T: Serialize>(path: &str, payload: &T, session: &LoginResponse) -> Result<(), String> {
    let body = serde_json::to_string(payload).map_err(|e| format!("Failed to serialize request: {e}"))?;

    let request = Request::post(&format!("{API_BASE}{path}"))
        .header("Authorization", &format!("Bearer {}", session.jwt))
        .header("x-session-id", &session.session_id)
        .header("Content-Type", "application/json")
        .body(body)
        .map_err(|e| format!("Request build failed: {e}"))?;

    let response = request.send().await.map_err(|e| format!("Request failed: {e}"))?;
    if response.ok() {
        Ok(())
    } else {
        Err(format!("HTTP {}", response.status()))
    }
}

async fn authed_post_json<TReq: Serialize, TResp: for<'de> Deserialize<'de>>(
    path: &str,
    payload: &TReq,
    session: &LoginResponse,
) -> Result<TResp, String> {
    let body = serde_json::to_string(payload).map_err(|e| format!("Failed to serialize request: {e}"))?;

    let request = Request::post(&format!("{API_BASE}{path}"))
        .header("Authorization", &format!("Bearer {}", session.jwt))
        .header("x-session-id", &session.session_id)
        .header("Content-Type", "application/json")
        .body(body)
        .map_err(|e| format!("Request build failed: {e}"))?;

    let response = request.send().await.map_err(|e| format!("Request failed: {e}"))?;
    if !response.ok() {
        return Err(format!("HTTP {}", response.status()));
    }

    response
        .json::<TResp>()
        .await
        .map_err(|e| format!("Failed to decode response: {e}"))
}

fn file_extension(file_name: &str) -> String {
    file_name
        .rsplit_once('.')
        .map(|(_, ext)| ext.to_ascii_lowercase())
        .unwrap_or_default()
}

fn is_allowed_ext(ext: &str) -> bool {
    matches!(ext, "jpg" | "jpeg" | "png" | "mp4" | "mp3" | "pdf" | "docx")
}

fn is_image_ext(ext: &str) -> bool {
    matches!(ext, "jpg" | "jpeg" | "png")
}

fn mime_for_ext(ext: &str) -> &'static str {
    match ext {
        "jpg" | "jpeg" => "image/jpeg",
        "png" => "image/png",
        "mp4" => "video/mp4",
        "mp3" => "audio/mpeg",
        "pdf" => "application/pdf",
        "docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        _ => "application/octet-stream",
    }
}

fn human_size(size: usize) -> String {
    if size >= 1024 * 1024 {
        format!("{:.2} MB", size as f64 / (1024.0 * 1024.0))
    } else if size >= 1024 {
        format!("{:.1} KB", size as f64 / 1024.0)
    } else {
        format!("{size} B")
    }
}
