+                    label { class: "block text-sm text-slate-700 mb-1", "Record ID" }
+                    input {
+                        class: "w-full sm:w-96 rounded-lg border border-slate-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500",
+                        value: "{record_id}",
