+                            return;
+                        };
+                        match authed_get_json::<Vec<AssetRow>>("/assets?page=1&limit=50", &session).await {
+                            Ok(data) => {
+                                rows_sig.set(data);
+                                status_sig.set("Assets loaded".to_string());
