+                {metric_card("Incident Rates", summary().incident_rate_count.to_string(), "bg-rose-50 border-rose-200")}
+            }
+
+            div { class: "mt-6 rounded-xl border border-slate-200 bg-white p-4",
+                button {
+                    class: "rounded-lg bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 font-semibold transition",
+                    onclick: move |_| {
+                        let session = auth.session();
+                        let mut summary_sig = summary;
+                        let mut status_sig = local_status;
+                        spawn_local(async move {
+                            status_sig.set("Loading dashboard metrics...".to_string());
+                            let Some(session) = session else {
+                                status_sig.set("Session missing".to_string());
+                                return;
+                            };
+
+                            match authed_get_json::<DashboardSummary>("/reports/dashboard", &session).await {
+                                Ok(data) => {
+                                    summary_sig.set(data);
+                                    status_sig.set("Dashboard refreshed".to_string());
+                                }
+                                Err(err) => status_sig.set(err),
+                            }
+                        });
+                    },
+                    "Refresh Dashboard"
+                }
+                p { class: "mt-3 text-sm text-slate-600", "{local_status}" }
+            }
+        }
+    }
+}
+
+#[component]
+fn Candidates() -> Element {
+    if !ensure_authenticated() {
+        return rsx! { div { class: "p-6", "Redirecting to login..." } };
+    }
+
+    let auth = use_context::<AuthContext>();
+    let mut rows = use_signal(Vec::<CandidateRow>::new);
+    let mut status = use_signal(|| "Load candidate records".to_string());
+
+    rsx! {
+        Shell { title: "Candidates", active: Route::Candidates {},
+            {panel_title("Candidate Management", "Review and search registered candidates")}
