+                            return;
+                        };
+                        match authed_get_json::<Vec<CandidateRow>>("/candidates?page=1&limit=50", &session).await {
+                            Ok(data) => {
+                                rows_sig.set(data);
+                                status_sig.set("Candidates loaded".to_string());
+                            }
+                            Err(err) => status_sig.set(err),
