+                                    label: "New Field".to_string(),
+                                    field_type: FieldType::Text,
+                                    required: false,
+                                    min_len: None,
+                                    max_len: None,
+                                });
+                                fields.set(state);
+                            },
+                            "Add Field"
+                        }
+
+                        button {
+                            class: "rounded-lg bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 text-sm font-semibold transition",
+                            onclick: move |_| {
