                }

                Err(dioxus_core::CapturedError::msg(
                    "File contents not available",
                ))
            }))
        }

        fn inner(&self) -> &dyn std::any::Any {
            self
        }

        fn path(&self) -> PathBuf {
            self.path.clone()
        }

        fn content_type(&self) -> Option<String> {
            self.content_type.clone()
        }
