+async fn authed_get_json<T: for<'de> Deserialize<'de>>(path: &str, session: &LoginResponse) -> Result<T, String> {
+    let response = Request::get(&format!("{API_BASE}{path}"))
+        .header("Authorization", &format!("Bearer {}", session.jwt))
+        .header("x-session-id", &session.session_id)
+        .send()
+        .await
+        .map_err(|e| format!("Request failed: {e}"))?;
+    if !response.ok() { return Err(format!("HTTP {}", response.status())); }
+    response.json::<T>().await.map_err(|e| format!("Decode failed: {e}"))
+}
+
+async fn authed_post_empty<T: Serialize>(path: &str, payload: &T, session: &LoginResponse) -> Result<(), String> {
+    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
+    let req = Request::post(&format!("{API_BASE}{path}"))
+        .header("Authorization", &format!("Bearer {}", session.jwt))
+        .header("x-session-id", &session.session_id)
+        .header("Content-Type", "application/json")
+        .body(body)
+        .map_err(|e| e.to_string())?;
+    let resp = req.send().await.map_err(|e| e.to_string())?;
+    if resp.ok() { Ok(()) } else { Err(format!("HTTP {}", resp.status())) }
+}
+
+async fn authed_post_json<TReq: Serialize, TResp: for<'de> Deserialize<'de>>(path: &str, payload: &TReq, session: &LoginResponse) -> Result<TResp, String> {
+    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
+    let req = Request::post(&format!("{API_BASE}{path}"))
+        .header("Authorization", &format!("Bearer {}", session.jwt))
+        .header("x-session-id", &session.session_id)
+        .header("Content-Type", "application/json")
+        .body(body)
+        .map_err(|e| e.to_string())?;
+    let resp = req.send().await.map_err(|e| e.to_string())?;
+    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
+    resp.json::<TResp>().await.map_err(|e| e.to_string())
+}
