+fn load_session_from_storage() -> Option<LoginResponse> {
+    let storage = web_sys::window()?.local_storage().ok().flatten()?;
+    let raw = storage.get_item(SESSION_STORAGE_KEY).ok().flatten()?;
+    serde_json::from_str::<LoginResponse>(&raw).ok()
+}
+fn save_session_to_storage(session: &LoginResponse) {
+    if let Some(storage) = web_sys::window().and_then(|w| w.local_storage().ok().flatten()) {
+        let _ = storage.set_item(SESSION_STORAGE_KEY, &serde_json::to_string(session).unwrap_or_default());
+    }
+}
+fn clear_session_from_storage() {
+    if let Some(storage) = web_sys::window().and_then(|w| w.local_storage().ok().flatten()) { let _ = storage.remove_item(SESSION_STORAGE_KEY); }
+}
