use dioxus::prelude::*;
use dioxus_router::{use_navigator, Link, Routable, Router};
use gloo_net::http::Request;
use gloo_timers::future::sleep;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use wasm_bindgen_futures::spawn_local;

const API_BASE: &str = "http://localhost:8000/api/v1";
const SESSION_STORAGE_KEY: &str = "proctorops_auth_session";

fn main() { dioxus::launch(App); }

#[derive(Routable, Clone, PartialEq, Debug)]
enum Route {
    #[route("/")] Login {},
    #[route("/dashboard")] Dashboard {},
    #[route("/candidates")] Candidates {},
    #[route("/rooms")] Rooms {},
    #[route("/sessions")] Sessions {},
    #[route("/assets")] Assets {},
    #[route("/reports")] Reports {},
    #[route("/templates")] Templates {},
    #[route("/outputs")] Outputs {},
    #[route("/admin")] Admin {},
    #[route("/:.._route")] NotFound { _route: Vec<String> },
}

#[derive(Debug, Deserialize, Serialize, Clone, Default)]
struct LoginResponse { session_id: String, jwt: String, session_expires_at: String, jwt_expires_at: String }
#[derive(Debug, Serialize)]
struct LoginRequest { username: String, password: String }
#[derive(Clone, Copy)]
struct AuthCtx { session: Signal<Option<LoginResponse>> }
#[derive(Clone, PartialEq)]
enum ToastKind { Success, Error, Info }
#[derive(Clone, PartialEq)]
struct Toast { id: i64, text: String, kind: ToastKind }
#[derive(Clone, Copy)]
struct ToastCtx { toast: Signal<Option<Toast>> }

#[derive(Debug, Deserialize, Clone, Default)]
struct DashboardSummary { total_candidates: i64, total_rooms: i64, total_sessions_this_week: i64, seat_utilization_count: usize, near_expiry_count: usize, incident_rate_count: usize, upcoming_sessions: Vec<UpcomingSession>, recent_outputs: Vec<RecentOutput> }
#[derive(Debug, Deserialize, Clone)]
struct UpcomingSession { id: String, template_name: String, status: String, starts_at: String }
#[derive(Debug, Deserialize, Clone)]
struct RecentOutput { id: String, output_type: String, mode: String, created_at: String }
#[derive(Debug, Deserialize, Clone)]
struct CandidateRow { id: String, scanned_barcode: String, national_id: String }
#[derive(Debug, Deserialize, Clone)]
struct RoomRow { id: String, capacity: i32, location: String }
#[derive(Debug, Deserialize, Clone)]
struct SessionRow { id: String, template_name: String, status: String, duration_minutes: i32 }
#[derive(Debug, Deserialize, Clone)]
struct AssetRow { id: String, booklet_code: String, tracking_status: String, incident_count: i32 }
#[derive(Debug, Deserialize, Clone)]
struct IncidentRow { session_id: String, avg_incidents: f64 }
#[derive(Debug, Deserialize, Clone)]
struct UserRow { username: String, role: String }
#[derive(Debug, Deserialize, Clone)]
struct TemplateRow { template_id: String, version_no: i32, locked_for_final_print: bool, created_at: String }

#[derive(Debug, Serialize)]
struct CreateCandidateRequest { candidate_id: String, date_of_birth: String, national_id: String, scanned_barcode: String, metadata_json: String }
#[derive(Debug, Serialize)]
struct CreateRoomRequest { id: String, capacity: i32, location: String }
#[derive(Debug, Serialize)]
struct ScanReq { code: String, intent: String }
#[derive(Debug, Deserialize)]
struct ScanResp { code: String, found: bool, candidate_id: Option<String> }
#[derive(Debug, Serialize)]
struct CreateUserRequest { username: String, password: String, role: String }
#[derive(Debug, Serialize)]
struct OutputReq { session_id: String, mode: String, output_type: String }
#[derive(Debug, Serialize)]
struct TemplateReq { template_id: String, version_no: i32, snapshot: serde_json::Value, lock_for_final_print: bool }

#[component]
fn App() -> Element {
    let session = use_signal(load_session);
    let toast = use_signal(|| None::<Toast>);
    use_context_provider(|| AuthCtx { session });
    use_context_provider(|| ToastCtx { toast });

    let toast_now = toast();
    use_effect(move || {
        if let Some(t) = toast_now {
            let mut sig = toast;
            spawn_local(async move {
                sleep(Duration::from_secs(3)).await;
                if sig().as_ref().map(|x| x.id) == Some(t.id) { sig.set(None); }
            });
        }
    });

    rsx! {
        document::Script { src: "https://cdn.tailwindcss.com" }
        Router::<Route> {}
        if let Some(t) = toast() {
            div { class: "fixed top-4 right-4 z-50 text-white px-4 py-2 rounded shadow-lg {toast_bg(&t.kind)}", "{t.text}" }
        }
    }
}

#[component]
fn Login() -> Element {
    let auth = use_context::<AuthCtx>();
    let nav = use_navigator();
    let mut username = use_signal(String::new);
    let mut password = use_signal(String::new);
    let sess = (auth.session)();
    use_effect(move || if sess.is_some() { nav.replace(Route::Dashboard {}) });
    rsx! {
        div { class: "min-h-screen bg-slate-100 flex items-center justify-center",
            div { class: "bg-white border rounded-xl p-6 w-full max-w-sm",
                h1 { class: "text-xl font-bold", "Login" }
                input { class: "mt-3 w-full border rounded px-3 py-2", placeholder: "Username", value: "{username}", oninput: move |e| username.set(e.value()) }
                input { r#type: "password", class: "mt-2 w-full border rounded px-3 py-2", placeholder: "Password", value: "{password}", oninput: move |e| password.set(e.value()) }
                button { class: "mt-3 w-full bg-blue-600 text-white rounded py-2", onclick: move |_| {
                    let payload = LoginRequest { username: username(), password: password() };
                    let mut ss = auth.session; let mut u = username; let mut p = password;
                    spawn_local(async move {
                        match post_json::<LoginRequest, LoginResponse>("/auth/login", &payload, None).await {
                            Ok(v) => { ss.set(Some(v.clone())); save_session(&v); toast("Login successful", ToastKind::Success); u.set(String::new()); p.set(String::new()); }
                            Err(e) => toast(&e, ToastKind::Error),
                        }
                    });
                }, "Sign In" }
            }
        }
    }
}
