fn require_auth() -> Option<LoginResponse> {
    let auth = use_context::<AuthCtx>();
    let nav = use_navigator();
    let s = (auth.session)();
    use_effect(move || if s.is_none() { nav.push(Route::Login {}) });
    s
}

#[component]
fn Dashboard() -> Element {
    let Some(sess) = require_auth() else { return rsx! { div { class: "p-6", "Redirecting..." } }; };
    let mut loading = use_signal(|| true);
    let mut loaded = use_signal(|| false);
    let mut summary = use_signal(DashboardSummary::default);
    if !loaded() {
        loaded.set(true);
        let mut l = loading; let mut s = summary;
        spawn_local(async move { match get_json::<DashboardSummary>("/dashboard/summary", Some(&sess)).await { Ok(v) => s.set(v), Err(e) => toast(&e, ToastKind::Error) } l.set(false); });
    }
    rsx! { Shell { title: "Dashboard", active: Route::Dashboard {}, if loading() { spinner() } else { dashboard_view(summary()) } } }
}

fn dashboard_view(s: DashboardSummary) -> Element {
    rsx! {
        div { class: "grid sm:grid-cols-3 gap-3",
            metric("Candidates", s.total_candidates.to_string())
            metric("Rooms", s.total_rooms.to_string())
            metric("Sessions This Week", s.total_sessions_this_week.to_string())
        }
        div { class: "mt-3 grid sm:grid-cols-3 gap-3",
            metric("Seat Utilization", s.seat_utilization_count.to_string())
            metric("Near Expiry", s.near_expiry_count.to_string())
            metric("Incident Rates", s.incident_rate_count.to_string())
        }
        div { class: "mt-3 grid lg:grid-cols-2 gap-3",
            div { class: "bg-white border rounded p-3", h3 { class: "font-bold", "Upcoming Sessions" }, if s.upcoming_sessions.is_empty() { p { class: "text-slate-500 text-sm mt-2", "No data" } } else { for r in s.upcoming_sessions { p { class: "text-sm mt-1", "{r.id} | {r.template_name} | {r.status} | {r.starts_at}" } } } }
            div { class: "bg-white border rounded p-3", h3 { class: "font-bold", "Recent Outputs" }, if s.recent_outputs.is_empty() { p { class: "text-slate-500 text-sm mt-2", "No data" } } else { for r in s.recent_outputs { p { class: "text-sm mt-1", "{r.id} | {r.output_type} | {r.mode} | {r.created_at}" } } } }
        }
        div { class: "mt-3 bg-white border rounded p-3", h3 { class: "font-bold", "Seat Utilization Trend (Mock)" }, svg { class: "w-full h-24", view_box: "0 0 400 100", polyline { points: "0,80 80,70 160,55 240,60 320,35 400,20", fill: "none", stroke: "#2563eb", stroke_width: "3" } } }
    }
}

#[component] fn Candidates() -> Element { candidates_page() }
#[component] fn Rooms() -> Element { rooms_page() }
#[component] fn Sessions() -> Element { list_page_sessions() }
#[component] fn Assets() -> Element { list_page_assets() }
#[component] fn Reports() -> Element { reports_page() }
#[component] fn Templates() -> Element { templates_page() }
#[component] fn Outputs() -> Element { outputs_page() }
#[component] fn Admin() -> Element { admin_page() }
#[component] fn NotFound(_route: Vec<String>) -> Element { rsx! { div { class: "p-8", Link { to: Route::Login {}, "Back" } } } }

fn candidates_page() -> Element {
    let Some(sess) = require_auth() else { return spinner(); };
    let mut loading = use_signal(|| true); let mut loaded = use_signal(|| false); let mut rows = use_signal(Vec::<CandidateRow>::new);
    let mut id = use_signal(String::new); let mut dob = use_signal(String::new); let mut nid = use_signal(String::new); let mut bar = use_signal(String::new); let mut meta = use_signal(String::new);
    if !loaded() { loaded.set(true); let mut l=loading; let mut r=rows; spawn_local(async move { match get_json::<Vec<CandidateRow>>("/candidates?page=1&limit=50", Some(&sess)).await { Ok(v)=>r.set(v), Err(e)=>toast(&e, ToastKind::Error)} l.set(false);}); }
    rsx! { Shell { title: "Candidates", active: Route::Candidates {},
        div { class: "bg-white border rounded p-3",
            h3 { class: "font-bold", "Create Candidate" }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "Candidate ID", value: "{id}", oninput: move |e| id.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "DOB (YYYY-MM-DD)", value: "{dob}", oninput: move |e| dob.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "National ID", value: "{nid}", oninput: move |e| nid.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "Barcode", value: "{bar}", oninput: move |e| bar.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 w-full", placeholder: "Metadata JSON", value: "{meta}", oninput: move |e| meta.set(e.value()) }
            button { class: "mt-2 bg-blue-600 text-white rounded px-4 py-2", onclick: move |_| {
                let p = CreateCandidateRequest { candidate_id:id(), date_of_birth:dob(), national_id:nid(), scanned_barcode:bar(), metadata_json:meta() };
                let s = sess.clone(); let mut a=id; let mut b=dob; let mut c=nid; let mut d=bar; let mut e=meta;
                spawn_local(async move { match post_empty("/candidates", &p, Some(&s)).await { Ok(_)=>{ toast("Candidate created", ToastKind::Success); a.set(String::new()); b.set(String::new()); c.set(String::new()); d.set(String::new()); e.set(String::new()); }, Err(err)=>toast(&err, ToastKind::Error)} });
            }, "Create" }
        }
        if loading() { spinner() } else { table_candidates(rows()) }
    } }
}

fn rooms_page() -> Element {
    let Some(sess) = require_auth() else { return spinner(); };
    let mut loading = use_signal(|| true); let mut loaded = use_signal(|| false); let mut rows = use_signal(Vec::<RoomRow>::new);
    let mut id = use_signal(String::new); let mut cap = use_signal(String::new); let mut loc = use_signal(String::new);
    if !loaded() { loaded.set(true); let mut l=loading; let mut r=rows; spawn_local(async move { match get_json::<Vec<RoomRow>>("/rooms?page=1&limit=50", Some(&sess)).await { Ok(v)=>r.set(v), Err(e)=>toast(&e, ToastKind::Error)} l.set(false);}); }
    rsx! { Shell { title: "Rooms", active: Route::Rooms {},
        div { class: "bg-white border rounded p-3",
            h3 { class: "font-bold", "Create Room" }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "Room ID", value: "{id}", oninput: move |e| id.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "Capacity", value: "{cap}", oninput: move |e| cap.set(e.value()) }
            input { class: "mt-2 border rounded px-3 py-2 mr-2", placeholder: "Location", value: "{loc}", oninput: move |e| loc.set(e.value()) }
            button { class: "mt-2 bg-blue-600 text-white rounded px-4 py-2", onclick: move |_| {
                let p = CreateRoomRequest { id:id(), capacity:cap().parse().unwrap_or(0), location:loc() }; let s = sess.clone(); let mut a=id; let mut b=cap; let mut c=loc;
                spawn_local(async move { match post_empty("/rooms", &p, Some(&s)).await { Ok(_)=>{ toast("Room created", ToastKind::Success); a.set(String::new()); b.set(String::new()); c.set(String::new()); }, Err(err)=>toast(&err, ToastKind::Error)} });
            }, "Create" }
        }
        if loading() { spinner() } else { table_rooms(rows()) }
    } }
}
