#[component]
fn Shell(title: &'static str, active: Route, children: Element) -> Element {
    let mut auth = use_context::<AuthCtx>();
    let nav = use_navigator();
    rsx! {
        div { class: "min-h-screen bg-slate-100 flex",
            aside { class: "hidden md:block w-64 bg-slate-900 text-white p-4", h2 { class: "font-bold text-xl mb-3", "ProctorOps" }
                {menu(Route::Dashboard {}, active == Route::Dashboard {}, "Dashboard")}
                {menu(Route::Candidates {}, active == Route::Candidates {}, "Candidates")}
                {menu(Route::Rooms {}, active == Route::Rooms {}, "Rooms")}
                {menu(Route::Sessions {}, active == Route::Sessions {}, "Sessions")}
                {menu(Route::Assets {}, active == Route::Assets {}, "Assets")}
                {menu(Route::Reports {}, active == Route::Reports {}, "Reports")}
                {menu(Route::Templates {}, active == Route::Templates {}, "Templates")}
                {menu(Route::Outputs {}, active == Route::Outputs {}, "Outputs")}
                {menu(Route::Admin {}, active == Route::Admin {}, "Admin")}
                button { class: "w-full mt-3 rounded bg-slate-700 py-2", onclick: move |_| { clear_session(); auth.session.set(None); nav.push(Route::Login {}); toast("Logged out", ToastKind::Info); }, "Logout" }
            }
            main { class: "flex-1 p-6", h1 { class: "text-2xl font-extrabold mb-3", "{title}" }, {children} }
        }
    }
