341	async fn get_json<T: for<'de> Deserialize<'de>>(path: &str, auth: Option<&LoginResponse>) -> Result<T, String> {
342	    let mut req = Request::get(&format!("{API_BASE}{path}"));
343	    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
344	    let resp = req.send().await.map_err(|e| e.to_string())?;
345	    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
346	    resp.json::<T>().await.map_err(|e| e.to_string())
347	}
