349	async fn post_empty<T: Serialize>(path: &str, payload: &T, auth: Option<&LoginResponse>) -> Result<(), String> {
350	    let mut req = Request::post(&format!("{API_BASE}{path}")).header("Content-Type", "application/json");
351	    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
352	    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
353	    let req = req.body(body).map_err(|e| e.to_string())?;
354	    let resp = req.send().await.map_err(|e| e.to_string())?;
355	    if resp.ok() { Ok(()) } else { Err(format!("HTTP {}", resp.status())) }
356	}
