358	async fn post_json<TReq: Serialize, TResp: for<'de> Deserialize<'de>>(path: &str, payload: &TReq, auth: Option<&LoginResponse>) -> Result<TResp, String> {
359	    let mut req = Request::post(&format!("{API_BASE}{path}")).header("Content-Type", "application/json");
360	    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
361	    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
362	    let req = req.body(body).map_err(|e| e.to_string())?;
363	    let resp = req.send().await.map_err(|e| e.to_string())?;
364	    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
365	    resp.json::<TResp>().await.map_err(|e| e.to_string())
366	}
