#[component]
fn Shell(title: &'static str, active: Route, children: Element) -> Element {
    let mut auth = use_context::<AuthCtx>();
    let nav = use_navigator();
    let role = (auth.session)()
        .as_ref()
        .map(jwt_role)
        .unwrap_or_else(|| "Auditor".to_string());
    rsx! {
        div { class: "min-h-screen bg-slate-100 flex",
            aside { class: "hidden md:block w-64 bg-slate-900 text-white p-4", h2 { class: "font-bold text-xl mb-3", "ProctorOps" }
                p { class: "text-xs text-slate-300 mb-2", "Role: {role}" }
                {menu(Route::Dashboard {}, active == Route::Dashboard {}, "Dashboard")}
                if role != "Auditor" { menu(Route::Candidates {}, active == Route::Candidates {}, "Candidates") }
                if role != "Auditor" { menu(Route::Rooms {}, active == Route::Rooms {}, "Rooms") }
                if role == "Admin" || role == "Coordinator" { menu(Route::Proctors {}, active == Route::Proctors {}, "Proctors") }
                if role == "Admin" || role == "Coordinator" { menu(Route::Exams {}, active == Route::Exams {}, "Exams") }
                if role != "Auditor" { menu(Route::Sessions {}, active == Route::Sessions {}, "Sessions") }
                if role != "Auditor" { menu(Route::Assets {}, active == Route::Assets {}, "Assets") }
                {menu(Route::Reports {}, active == Route::Reports {}, "Reports")}
                if role == "Admin" || role == "Coordinator" { menu(Route::Templates {}, active == Route::Templates {}, "Templates") }
                if role != "Auditor" { menu(Route::Outputs {}, active == Route::Outputs {}, "Outputs") }
                if role == "Admin" { menu(Route::Admin {}, active == Route::Admin {}, "Admin") }
                button { class: "w-full mt-3 rounded bg-slate-700 py-2", onclick: move |_| { clear_session(); auth.session.set(None); nav.push(Route::Login {}); toast("Logged out", ToastKind::Info); }, "Logout" }
            }
            main { class: "flex-1 p-6", h1 { class: "text-2xl font-extrabold mb-3", "{title}" }, {children} }
        }
    }
}

fn jwt_role(session: &LoginResponse) -> String {
    let parts: Vec<&str> = session.jwt.split('.').collect();
    if parts.len() < 2 {
        return "Auditor".to_string();
    }
    let payload = parts[1].replace('-', "+").replace('_', "/");
    let padded = match payload.len() % 4 {
        2 => format!("{payload}=="),
        3 => format!("{payload}="),
        _ => payload,
    };
    let decoded = base64::engine::general_purpose::STANDARD.decode(padded);
    let Ok(bytes) = decoded else {
        return "Auditor".to_string();
    };
    let parsed: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
    parsed
        .get("role")
        .and_then(|v| v.as_str())
        .unwrap_or("Auditor")
        .to_string()
}

fn menu(route: Route, active: bool, label: &'static str) -> Element { let cls = if active { "block rounded bg-blue-600 px-3 py-2 mb-1" } else { "block rounded hover:bg-slate-800 px-3 py-2 mb-1" }; rsx!{ Link { class: "{cls}", to: route, "{label}" } } }
fn metric(title: &'static str, value: String) -> Element { rsx!{ div { class: "bg-white border rounded p-3", p { class: "text-sm text-slate-500", "{title}" } p { class: "text-xl font-bold", "{value}" } } } }
fn spinner() -> Element { rsx!{ div { class: "bg-white border rounded p-3 text-slate-600", "Loading..." } } }
fn toast_bg(k: &ToastKind) -> &'static str { match k { ToastKind::Success => "bg-emerald-600", ToastKind::Error => "bg-rose-600", ToastKind::Info => "bg-slate-700" } }

fn toast(msg: &str, kind: ToastKind) {
    let mut ctx = consume_context::<ToastCtx>();
    ctx.toast
        .set(Some(Toast { id: js_sys::Date::now() as i64, text: msg.to_string(), kind }));
}

async fn get_json<T: for<'de> Deserialize<'de>>(path: &str, auth: Option<&LoginResponse>) -> Result<T, String> {
    let mut req = Request::get(&format!("{}{path}", api_base()));
    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
    let resp = req.send().await.map_err(|e| e.to_string())?;
    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
    resp.json::<T>().await.map_err(|e| e.to_string())
}

async fn post_empty<T: Serialize>(path: &str, payload: &T, auth: Option<&LoginResponse>) -> Result<(), String> {
    let mut req = Request::post(&format!("{}{path}", api_base())).header("Content-Type", "application/json");
    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
    let req = req.body(body).map_err(|e| e.to_string())?;
    let resp = req.send().await.map_err(|e| e.to_string())?;
    if resp.ok() { Ok(()) } else { Err(format!("HTTP {}", resp.status())) }
}

async fn post_json<TReq: Serialize, TResp: for<'de> Deserialize<'de>>(path: &str, payload: &TReq, auth: Option<&LoginResponse>) -> Result<TResp, String> {
    let mut req = Request::post(&format!("{}{path}", api_base())).header("Content-Type", "application/json");
    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
    let body = serde_json::to_string(payload).map_err(|e| e.to_string())?;
    let req = req.body(body).map_err(|e| e.to_string())?;
    let resp = req.send().await.map_err(|e| e.to_string())?;
    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
    resp.json::<TResp>().await.map_err(|e| e.to_string())
}

fn load_session() -> Option<LoginResponse> {
    let storage = web_sys::window()?.local_storage().ok().flatten()?;
    let raw = storage.get_item(SESSION_STORAGE_KEY).ok().flatten()?;
    serde_json::from_str::<LoginResponse>(&raw).ok()
}
fn save_session(s: &LoginResponse) { if let Some(st) = web_sys::window().and_then(|w| w.local_storage().ok().flatten()) { let _ = st.set_item(SESSION_STORAGE_KEY, &serde_json::to_string(s).unwrap_or_default()); } }
fn clear_session() { if let Some(st) = web_sys::window().and_then(|w| w.local_storage().ok().flatten()) { let _ = st.remove_item(SESSION_STORAGE_KEY); } }

fn table_candidates(rows: Vec<CandidateRow>) -> Element { rsx!{ div { class: "mt-3 bg-white border rounded p-3 overflow-auto", for r in rows { p { "{r.id} | {r.scanned_barcode} | {r.national_id}" } } } } }
fn table_rooms(rows: Vec<RoomRow>) -> Element { rsx!{ div { class: "mt-3 bg-white border rounded p-3 overflow-auto", for r in rows { p { "{r.id} | {r.capacity} | {r.location}" } } } } }
fn table_sessions(rows: Vec<SessionRow>) -> Element { rsx!{ div { class: "mt-3 bg-white border rounded p-3 overflow-auto", for r in rows { p { "{r.id} | {r.template_name} | {r.status} | {r.duration_minutes}" } } } } }
fn table_assets(rows: Vec<AssetRow>) -> Element { rsx!{ div { class: "mt-3 bg-white border rounded p-3 overflow-auto", for r in rows { p { "{r.id} | {r.booklet_code} | {r.tracking_status} | {r.incident_count}" } } } } }

