451:fn jwt_role(session: &LoginResponse) -> String {
452:    let parts: Vec<&str> = session.jwt.split('.').collect();
453:    if parts.len() < 2 {
454:        return "Auditor".to_string();
455:    }
456:    let payload = parts[1].replace('-', "+").replace('_', "/");
457:    let padded = match payload.len() % 4 {
458:        2 => format!("{payload}=="),
459:        3 => format!("{payload}="),
460:        _ => payload,
461:    };
462:    let decoded = base64::engine::general_purpose::STANDARD.decode(padded);
463:    let Ok(bytes) = decoded else {
464:        return "Auditor".to_string();
465:    };
466:    let parsed: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
467:    parsed
468:        .get("role")
469:        .and_then(|v| v.as_str())
470:        .unwrap_or("Auditor")
471:        .to_string()
472:}
