484:async fn get_json<T: for<'de> Deserialize<'de>>(path: &str, auth: Option<&LoginResponse>) -> Result<T, String> {
485:    let mut req = Request::get(&format!("{}{path}", api_base()));
486:    if let Some(a) = auth { req = req.header("Authorization", &format!("Bearer {}", a.jwt)).header("x-session-id", &a.session_id); }
487:    let resp = req.send().await.map_err(|e| e.to_string())?;
488:    if !resp.ok() { return Err(format!("HTTP {}", resp.status())); }
489:    resp.json::<T>().await.map_err(|e| e.to_string())
490:}
